package com.neu.riketiku.shijuan;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.List;
public final class PaperDtos{private PaperDtos(){}public record ItemInput(@NotNull Long questionId,@NotNull @DecimalMin("0.01") BigDecimal score){}public record Save(@NotNull Long subjectId,@NotBlank @Size(max=120) String name,@NotBlank String mode,@NotEmpty List<ItemInput> items){}public record Rule(@NotNull Long subjectId,@NotBlank @Size(max=120) String name,List<Long> knowledgePointIds,List<String> questionTypes,List<Integer> difficulties,@NotNull @Min(1) @Max(100) Integer count,@NotNull @DecimalMin("0.01") BigDecimal totalScore){}public record Option(String label,String content){}public record QuestionOption(Long id,String type,String stem,int difficulty,List<String> knowledgePoints){}public record Question(Long id,int order,BigDecimal score,String type,String stem,int difficulty,List<Option> options,String correctAnswer,String standardAnalysis,List<String> knowledgePoints){}public record Paper(Long id,Long subjectId,String subjectName,String name,String mode,BigDecimal totalScore,String status,List<Question> questions){}public record ListItem(Long id,String name,String mode,BigDecimal totalScore,String status,int questionCount){} }
